test("browser semantics reject inert policy, inert script, and quoted-tag-boundary mutants", async ({
  browser,
}) => {
  test.setTimeout(120_000);
  const policyTag =
    `<meta http-equiv="Content-Security-Policy" content="${PAGE_CONTENT_SECURITY_POLICY}">`;
  const canonicalScript = '<script src="app.js" defer></script>';
  const headContentStart = pageSource.indexOf("<head>") + "<head>".length;
  const headContentEnd = pageSource.indexOf("</head>");
  const bodyContentStart = pageSource.indexOf("<body>") + "<body>".length;
  const policyAndResourcesInBody =
    pageSource.slice(0, headContentStart) +
    pageSource.slice(headContentEnd, bodyContentStart) +
    pageSource.slice(headContentStart, headContentEnd) +
    pageSource.slice(bodyContentStart);
  const pageWithoutPolicy = pageSource.replace(policyTag, "");
  const pageMutants = new Map([
    ["missing policy", pageWithoutPolicy],
    ["commented policy", pageSource.replace(policyTag, `<!-- ${policyTag} -->`)],
    ["bogus-comment policy", pageSource.replace(policyTag, `<!x ${policyTag}`)],
    ["template policy", pageSource.replace(policyTag, `<template>${policyTag}</template>`)],
    [
      "policy after a resource",
      pageWithoutPolicy.replace(
        `<link rel="icon" href="${PAGE_BRAND_LOGO_PATH}">`,
        `<link rel="icon" href="${PAGE_BRAND_LOGO_PATH}">\n  ${policyTag}`,
      ),
    ],
    ["duplicate policy", pageSource.replace(policyTag, `${policyTag}\n  ${policyTag}`)],
    ["policy and resources in body", policyAndResourcesInBody],
    [
      "external script",
      pageSource.replace(
        canonicalScript,
        '<script src="https://example.com/app.js" defer></script>',
      ),
    ],
    [
      "template script",
      pageSource.replace(canonicalScript, `<template>${canonicalScript}</template>`),
    ],
    [
      "noscript script",
      pageSource.replace(canonicalScript, `<noscript>${canonicalScript}</noscript>`),
    ],
    [
      "quoted greater-than in stylesheet URL",
      pageSource.replace(
        '<link rel="stylesheet" href="styles.css">',
        '<link rel="stylesheet" href="styles.css>https://example.com/untracked.css">',
      ),
    ],
    [
      "untracked image",
      pageSource.replace(
        "</main>",
        '<img src="https://example.com/untracked.png" alt="">\n</main>',
      ),
    ],
    [
      "srcdoc subdocument",
      pageSource.replace(
        "</main>",
        `<iframe srcdoc="&lt;img src='${BRAND_LOGO_URL}'&gt;"></iframe>\n</main>`,
      ),
    ],
  ]);

  for (const [name, html] of pageMutants) {
    expect(html, `${name} must change the document`).not.toBe(pageSource);
    let rejected = false;
    try {
      await assertPagesSemantics(browser, { html });
    } catch {
      rejected = true;
    }
    expect(rejected, `${name} must be rejected`).toBe(true);
  }
});

test("browser network inventory rejects dynamic query and CSS resource drift", async ({
  browser,
}) => {
  const cacheMutationTarget =
    'img.src += (img.src.includes("?") ? "&" : "?") + "cb=" + cb;';
  const queryDriftScript = scriptSource.replace(
    cacheMutationTarget,
    `${cacheMutationTarget.slice(0, -1)} + "&uncatalogued=1";`,
  );
  const hiddenRequestScript = scriptSource.replace(
    '"use strict";',
    `"use strict";\n  const untrackedImage = new Image();\n  untrackedImage.src = "${PAGE_DEVICON_PREFIX}${DEVICON_PATHS[0]}?uncatalogued=1";`,
  );
  const delayedRequestScript = scriptSource.replace(
    '"use strict";',
    `"use strict";\n  setTimeout(() => {\n    const delayedImage = new Image();\n    delayedImage.src = "${PAGE_DEVICON_PREFIX}${DEVICON_PATHS[0]}?uncatalogued=delayed";\n  }, 2147483646);`,
  );
  const eventRequestScript = scriptSource.replace(
    '"use strict";',
    `"use strict";\n  document.addEventListener("click", () => {\n    const eventImage = new Image();\n    eventImage.src = "${PAGE_DEVICON_PREFIX}${DEVICON_PATHS[0]}?uncatalogued=event";\n  }, { once: true });`,
  );
  const deferredEventUrl =
    `${PAGE_DEVICON_PREFIX}${DEVICON_PATHS[0]}?uncatalogued=deferred-event`;
  const deferredEventRequestScript = scriptSource.replace(
    '"use strict";',
    `"use strict";\n  setTimeout(() => {\n    document.addEventListener("click", (event) => {\n      if (!event.isTrusted) return;\n      const deferredEventImage = new Image();\n      deferredEventImage.src = "${deferredEventUrl}";\n    }, { once: true });\n  }, 1000);`,
  );
  const deferredKeyboardUrl =
    `${PAGE_DEVICON_PREFIX}${DEVICON_PATHS[0]}?uncatalogued=deferred-keyboard`;
  const deferredKeyboardRequestScript = scriptSource.replace(
    '"use strict";',
    `"use strict";\n  setTimeout(() => {\n    document.addEventListener("keydown", (event) => {\n      if (!event.isTrusted) return;\n      const deferredKeyboardImage = new Image();\n      deferredKeyboardImage.src = "${deferredKeyboardUrl}";\n    }, { once: true });\n  }, 1000);`,
  );
  const stylesheetDrift =
    `${stylesheetSource}\nbody { background-image: url("${PAGE_DEVICON_PREFIX}${DEVICON_PATHS[0]}?uncatalogued=1"); }`;

  for (const [name, mutation, expectedUnknownRequest] of [
    ["analytics query", { script: queryDriftScript }],
    ["detached image request", { script: hiddenRequestScript }],
    ["delayed image request", { script: delayedRequestScript }],
    ["event-driven image request", { script: eventRequestScript }],
    [
      "deferred trusted-interaction request",
      { script: deferredEventRequestScript },
      deferredEventUrl,
    ],
    [
      "deferred trusted-keyboard request",
      { script: deferredKeyboardRequestScript },
      deferredKeyboardUrl,
    ],
    ["stylesheet request", { stylesheet: stylesheetDrift }],
  ]) {
    let failure;
    try {
      await assertPagesSemantics(browser, mutation);
    } catch (error) {
      failure = error;
    }
    expect(failure, `${name} drift must be rejected`).toBeDefined();
    if (expectedUnknownRequest) {
      expect(String(failure), `${name} must fail on its exact URL`).toContain(
        expectedUnknownRequest,
      );
    }
  }
});

